# Generated by build.py from recipe.yml for recipe ldap-search-a-directory. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site/.surl/ldap
cat > site/.surl/ldap/directory.ldif <<'EOF'
dn: dc=example,dc=com
objectClass: domain
dc: example

dn: cn=alice,dc=example,dc=com
objectClass: person
cn: alice
sn: Liddell
mail: alice@example.com

dn: cn=bob,dc=example,dc=com
objectClass: person
cn: bob
sn: Builder
mail: bob@example.com
EOF
surl --directory site --allow-plaintext-auth -u alice:s3cret ldap://127.0.0.1:8080/ &
sleep 1
curl -u alice:s3cret "ldap://127.0.0.1:8080/dc=example,dc=com?cn,mail?sub?(objectClass=person)"
kill $(jobs -p)
